download::DownloadItemImpl* CreateActiveDownloadItem(uint32_t id, const download::DownloadCreateInfo& info) {
    // Check if the download item already exists
    if (download::DownloadManager::GetInstance()->ContainsDownload(id)) {
        return nullptr;
    }

    // Create a new download item
    download::DownloadItemImpl* new_download = new download::DownloadItemImpl(id, info);
    if (!new_download) {
        return nullptr;
    }

    // Store the new download item in the downloads map
    download::DownloadManager::GetInstance()->AddDownload(id, new_download);

    // Attach additional information to the download item
    new_download->AttachAdditionalInfo(info.additional_info);

    return new_download;
}

